// Normaliza o payload da Evolution e decide se vale processar.
//
// ## O `.body` nao e detalhe: sem ele, TUDO e descartado
//
// O no de webhook do n8n nao entrega o corpo cru. Ele embrulha:
// `{ headers, params, query, body, webhookUrl }`. Ler a raiz devolve
// `undefined` em cada campo, `texto` vira '' e `processar` vira false — a
// execucao aparece como SUCESSO, some pelo ramo do Ignora, e nao ha erro
// nenhum para investigar.
//
// Foi exatamente o que aconteceu na primeira prova: execucao 1, status
// success, mensagem descartada em silencio.
//
// O `?? j` no fim cobre o caso de a Evolution ser apontada para um proxy que
// entregue o corpo cru.
//
// ## Dois cortes que evitam desastre
//
// A Evolution manda TODO evento, inclusive o que o proprio numero envia
// (`fromMe: true`). Sem o corte, o agente responde a si mesmo — laco infinito
// que so para quando o numero e banido.
//
// Grupo fica de fora (`@g.us`): responder em grupo expoe a conversa comercial
// para gente que nunca pediu nada.
const j = $input.first().json;
const e = j.body ?? j;
const d = e.data || {};
const k = d.key || {};

const texto =
  d.message?.conversation ??
  d.message?.extendedTextMessage?.text ??
  '';

const jid = k.remoteJid || '';
const numero = jid.split('@')[0];

const processar =
  e.event === 'messages.upsert' &&
  k.fromMe !== true &&
  !jid.endsWith('@g.us') &&
  texto.trim().length > 0;

return [{ json: {
  processar,
  numero,
  nome: d.pushName || null,
  texto: texto.trim(),
  instancia: e.instance || null,
} }];
